records.detail:
body { 
    font-family: 'Orbitron', sans-serif; 
    margin: 0; 
    padding: 0; 
    background: linear-gradient(to right, #2b5876, #4e4376); 
    color: #fff; 
} 

header { 
    background: linear-gradient(to right, #ff6e7f, #bfe9ff); 
    color: #fff; 
    padding: 1em 0; 
    text-align: center; 
    font-size: 2em; 
    font-weight: bold; 
    text-transform: uppercase; 
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1); 
} 

nav a { 
    color: #fff; 
    margin: 0 15px; 
    text-decoration: none; 
    font-weight: bold; 
    transition: color 0.3s ease; 
} 

nav a:hover { 
    color: #ff6e7f; 
} 

main { 
    padding: 20px; 
} 

form { 
    background: rgba(0, 0, 0, 0.7); 
    padding: 20px; 
    margin: 20px 0; 
    box-shadow: 0 0 10px rgba(255, 110, 127, 0.5); 
    border-radius: 8px; 
} 

form label { 
    display: block; 
    margin: 10px 0 5px; 
    color: #ff6e7f; 
} 

form input[type="text"], 
form input[type="password"], 
form input[type="email"], 
form input[type="file"], 
form input[type="url"] { 
    width: 100%; 
    padding: 10px; 
    margin-bottom: 10px; 
    border: none; 
    border-radius: 4px; 
    background: rgba(255, 255, 255, 0.1); 
    color: #fff; 
    font-size: 1em; 
} 

form button { 
    padding: 10px 15px; 
    background-color: #ff6e7f; 
    color: #fff; 
    border: none; 
    cursor: pointer; 
    border-radius: 4px; 
    font-size: 1em; 
    transition: background-color 0.3s ease; 
} 

form button:hover { 
    background-color: #ff4e7f; 
} 

h2 { 
    color: #ff6e7f; 
} 

ul { 
    list-style-type: none; 
    padding: 0; 
} 

ul li { 
    background: rgba(0, 0, 0, 0.7); 
    padding: 10px; 
    margin: 5px 0; 
    border-radius: 4px; 
} 

img { 
    max-width: 100%; 
    border-radius: 8px; 
    box-shadow: 0 0 10px rgba(255, 110, 127, 0.5); 
} 

.register-link { 
    text-align: center; 
    margin-top: 20px; 
} 

.register-link a { 
    color: #ff6e7f; 
    text-decoration: none; 
    font-weight: bold; 
} 

.register-link a:hover { 
    text-decoration: underline; 
}
